import path from 'node:path';
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
const require=createRequire(import.meta.url);
const {chromium}=require(process.env.PLAYWRIGHT_MODULE||'/Users/panglaohu/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
const out=path.resolve(process.argv[2]||'TigerMessenger/artifacts/workshop-tests/manual');fs.mkdirSync(out,{recursive:true});
const base=process.env.WORKSHOP_BASE_URL||'http://localhost:8931';
const browser=await chromium.launch({headless:true,executablePath:process.env.CHROME_PATH||'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'});
const context=await browser.newContext({acceptDownloads:true,viewport:{width:1440,height:1000}}),page=await context.newPage();page.setDefaultTimeout(12000);
// Observe stalls without relaxing interaction deadlines or replacing the real game.
await context.addInitScript(()=>{globalThis.workshopLongTasks=[];try{new PerformanceObserver(list=>{for(const entry of list.getEntries())globalThis.workshopLongTasks.push({start:Math.round(entry.startTime),duration:Math.round(entry.duration)});globalThis.workshopLongTasks.sort((a,b)=>b.duration-a.duration);globalThis.workshopLongTasks.length=Math.min(20,globalThis.workshopLongTasks.length);}).observe({type:'longtask',buffered:true});}catch{globalThis.workshopLongTasksUnsupported=true;}});
const report={startedAt:new Date().toISOString(),base,isolated:true,cases:[],errors:[]};
async function responsiveness(){return Promise.all(page.frames().map(async frame=>{try{return await frame.evaluate(()=>({url:location.pathname,ageMs:Math.round(performance.now()),readyState:document.readyState,visibility:document.visibilityState,longTasks:globalThis.workshopLongTasks||[],unsupported:!!globalThis.workshopLongTasksUnsupported}));}catch{return {detached:true};}}));}
page.on('pageerror',e=>report.errors.push(e.message));
async function check(id,fn){const filter=process.env.WORKSHOP_CASES?.split(',');if(filter&&!filter.includes(id.split(' ')[0])){report.cases.push({id,status:'NOT_RUN',reason:'targeted test filter'});return;}const start=Date.now();try{const detail=await fn();report.cases.push({id,status:'PASS',ms:Date.now()-start,detail});}catch(e){report.cases.push({id,status:'FAIL',ms:Date.now()-start,error:e.message,responsiveness:await responsiveness(),diagnostic:await page.evaluate(()=>({cache:document.querySelector('#learning-cache-status')?.textContent,progress:document.querySelector('#learning-progress')?.dataset.state,notice:document.querySelector('#learning-progress [role=status]')?.textContent,version:document.querySelector('#learning-workshop')?.dataset.snapshotId})).catch(()=>null)});}fs.writeFileSync(path.join(out,'browser.json'),JSON.stringify(report,null,2));}
const click=async id=>{if(id==='scan'&&!await page.locator('#library-source-tools').evaluate(el=>el.open))await page.locator('#library-source-tools>summary').click();return page.locator('#'+id).click();};
const recipe=()=>page.evaluate(()=>{const d={};dispatchEvent(new CustomEvent('tm.pipeline.capture',{detail:d}));return d.recipe;});
const nodes=()=>page.locator('#pipeline .node');
const versionStatus=()=>page.locator('#scene-authoring [role=status]').textContent();
